{"command":"python3 -c '
import subprocess

for sh in ["posix", "zsh"]:
    actual = subprocess.run(["./executable", "init", sh, "--cmd", "foo"], capture_output=True, text=True).stdout
    with open(f"src/templates/{sh}_pwd_cmd.txt") as f:
        template = f.read()

    print(f"=== {sh} diff ===")
    import difflib
    for line in difflib.unified_diff(template.splitlines(), actual.splitlines()):
        if line.startswith("+") or line.startswith("-"):
            print(line)
'"}

