{"command":"cat << 'EOF' > src/db.rs
use std::env;
use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Component, Path, PathBuf};

#[derive(Debug, Clone)]
pub struct Dir {
    pub path: String,
    pub rank: f64,
    pub last_accessed: u64,
}

impl Dir {
    pub fn query_score(&self, now: u64) -> f64 {
        let delta = now.saturating_sub(self.last_accessed);
        let multiplier = if delta < 3600 {
            4.0
        } else if delta < 86400 {
            2.0
        } else if delta < 604800 {
            0.5
        } else {
            0.25
        };
        self.rank * multiplier
    }
}

pub struct Database {
    pub dirs: Vec<Dir>,
}

impl Database {
    pub fn read(path: &Path) -> anyhow::Result<Self> {
        if !path.exists() {
            return Ok(Database { dirs: Vec::new() });
        }
        let mut file = File::open(path)?;
        let mut buf = Vec::new();
        file.read_to_end(&mut buf)?;
        if buf.len() < 12 {
            return Ok(Database { dirs: Vec::new() });
        }
        let header = u32::from_le_bytes(buf[0..4].try_into().map_err(|_| anyhow::anyhow!("invalid header"))?);
        if header != 3 {
            return Ok(Database { dirs: Vec::new() });
        }
        let count = u64::from_le_bytes(buf[4..12].try_into().map_err(|_| anyhow::anyhow!("invalid count"))?) as usize;
        let mut offset = 12;
        let mut dirs = Vec::with_capacity(count);
        for _ in 0..count {
            if offset + 8 > buf.len() {
                break;
            }
            let path_len = u64::from_le_bytes(buf[offset..offset + 8].try_into().unwrap()) as usize;
            offset += 8;
            if offset + path_len + 16 > buf.len() {
                break;
            }
            let path_str = String::from_utf8_lossy(&buf[offset..offset + path_len]).to_string();
            offset += path_len;
            let rank = f64::from_le_bytes(buf[offset..offset + 8].try_into().unwrap());
            offset += 8;
            let last_accessed = u64::from_le_bytes(buf[offset..offset + 8].try_into().unwrap());
            offset += 8;
            dirs.push(Dir {
                path: path_str,
                rank,
                last_accessed,
            });
        }
        Ok(Database { dirs })
    }

    pub fn save(&self, path: &Path) -> anyhow::Result<()> {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let mut buf = Vec::new();
        buf.extend_from_slice(&3u32.to_le_bytes());
        buf.extend_from_slice(&(self.dirs.len() as u64).to_le_bytes());
        for dir in &self.dirs {
            let path_bytes = dir.path.as_bytes();
            buf.extend_from_slice(&(path_bytes.len() as u64).to_le_bytes());
            buf.extend_from_slice(path_bytes);
            buf.extend_from_slice(&dir.rank.to_le_bytes());
            buf.extend_from_slice(&dir.last_accessed.to_le_bytes());
        }
        fs::write(path, buf)?;
        Ok(())
    }
}

pub fn get_db_path() -> anyhow::Result<PathBuf> {
    if let Ok(dir) = env::var("_ZO_DATA_DIR") {
        return Ok(PathBuf::from(dir).join("db.zo"));
    }
    if let Ok(data_home) = env::var("XDG_DATA_HOME") {
        if !data_home.is_empty() {
            return Ok(PathBuf::from(data_home).join("zoxide").join("db.zo"));
        }
    }
    if let Some(data_dir) = dirs::data_dir() {
        return Ok(data_dir.join("zoxide").join("db.zo"));
    }
    anyhow::bail!("unable to determine data directory")
}

pub fn resolve_path(p: &str, resolve_symlinks: bool) -> anyhow::Result<String> {
    let path = Path::new(p);
    if resolve_symlinks {
        let canonical = fs::canonicalize(path)?;
        Ok(canonical.to_string_lossy().to_string())
    } else {
        let abs = if path.is_absolute() {
            path.to_path_buf()
        } else {
            env::current_dir()?.join(path)
        };
        Ok(normalize_path(&abs))
    }
}

pub fn normalize_path(path: &Path) -> String {
    let mut components = Vec::new();
    for component in path.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                if let Some(Component::Normal(_)) = components.last() {
                    components.pop();
                }
            }
            c => components.push(c),
        }
    }
    let mut res = PathBuf::new();
    for c in components {
        res.push(c);
    }
    res.to_string_lossy().to_string()
}

pub fn is_excluded(path_str: &str) -> anyhow::Result<bool> {
    let exclude_dirs_env = env::var("_ZO_EXCLUDE_DIRS");
    let exclude_patterns = match exclude_dirs_env {
        Ok(ref s) => {
            if s.is_empty() {
                Vec::new()
            } else {
                s.split(':').map(|x| x.to_string()).collect::<Vec<_>>()
            }
        }
        Err(_) => {
            if let Some(home) = dirs::home_dir() {
                vec![home.to_string_lossy().to_string()]
            } else {
                Vec::new()
            }
        }
    };

    for pat_str in exclude_patterns {
        let pattern = glob::Pattern::new(&pat_str).map_err(|e| {
            anyhow::anyhow!("zoxide: invalid glob in _ZO_EXCLUDE_DIRS: {}\n\nCaused by:\n    {}", pat_str, e)
        })?;
        if pattern.matches(path_str) {
            return Ok(true);
        }
    }
    Ok(false)
}

pub fn get_max_age() -> anyhow::Result<u64> {
    if let Ok(val) = env::var("_ZO_MAXAGE") {
        val.parse::<u64>().map_err(|e| {
            anyhow::anyhow!("zoxide: unable to parse _ZO_MAXAGE as integer: {}\n\nCaused by:\n    {}", val, e)
        })
    } else {
        Ok(10000)
    }
}

pub fn age_database(db: &mut Database, max_age: u64) {
    if max_age == 0 {
        return;
    }
    let total_score: f64 = db.dirs.iter().map(|d| d.rank).sum();
    if total_score > max_age as f64 {
        let factor = (max_age as f64 * 0.9) / total_score;
        for dir in &mut db.dirs {
            dir.rank *= factor;
        }
        db.dirs.retain(|d| d.rank >= 1.0);
    }
}
EOF"}

