    let total_score: f64 = db.dirs.iter().map(|d| d.rank).sum();
    if total_score > max_age as f64 {
        let factor = (max_age as f64 * 0.9) / total_score;
        for dir in &mut db.dirs {
            dir.rank *= factor;
        }
        db.dirs.retain(|d| d.rank >= 1.0);
    }
}
