use crate::db::Dir;
use std::cmp::Ordering;
use std::path::Path;

pub fn matches_keywords(path_str: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() {
        return true;
    }

    let components: Vec<&str> = Path::new(path_str)
        .components()
        .filter_map(|c| c.as_os_str().to_str())
        .collect();

    if components.is_empty() {
        return false;
    }

    let num_comp = components.len();
    let num_kw = keywords.len();

    let mut current_comp_idx = 0;

    for (i, kw) in keywords.iter().enumerate() {
        let is_last = i == num_kw - 1;
        let kw_lower = kw.to_lowercase();

        if is_last {
            if kw == "/" {
                return current_comp_idx < num_comp;
            } else if kw.ends_with('/') {
                let prefix = kw_lower.trim_end_matches('/');
                let mut found = false;
                for idx in current_comp_idx..num_comp {
                    if components[idx].to_lowercase().contains(prefix) {
                        if idx < num_comp - 1 {
                            found = true;
                            break;
                        }
                    }
                }
                return found;
            } else if kw.contains('/') {
                let sub_kws: Vec<&str> = kw_lower.split('/').collect();
                let sub_len = sub_kws.len();
                if sub_len > num_comp {
                    return false;
                }
                let start_idx = num_comp - sub_len;
                if start_idx < current_comp_idx {
                    return false;
                }
                for j in 0..sub_len {
                    if !components[start_idx + j].to_lowercase().contains(sub_kws[j]) {
                        return false;
                    }
                }
                return true;
            } else {
                let last_comp = components[num_comp - 1].to_lowercase();
                return last_comp.contains(&kw_lower);
            }
        } else {
            if kw == "/" {
                // Stay at current_comp_idx
            } else if kw.contains('/') {
                let sub_kws: Vec<&str> = kw_lower.split('/').collect();
                let sub_len = sub_kws.len();
                let mut matched = false;
                for start in current_comp_idx..=num_comp.saturating_sub(sub_len) {
                    let mut ok = true;
                    for j in 0..sub_len {
                        if !components[start + j].to_lowercase().contains(sub_kws[j]) {
                            ok = false;
                            break;
                        }
                    }
                    if ok {
                        current_comp_idx = start + sub_len;
                        matched = true;
                        break;
                    }
                }
                if !matched {
                    return false;
                }
            } else {
                let mut matched = false;
                for idx in current_comp_idx..num_comp {
                    if components[idx].to_lowercase().contains(&kw_lower) {
                        current_comp_idx = idx + 1;
                        matched = true;
                        break;
                    }
                }
                if !matched {
                    return false;
                }
            }
        }
    }

    true
}

pub fn query_matches<'a>(
    dirs: &'a [Dir],
    keywords: &[String],
    now: u64,
    all: bool,
    exclude: Option<&str>,
    base_dir: Option<&str>,
) -> Vec<(&'a Dir, f64)> {
    let mut matches = Vec::new();

    for dir in dirs {
        if !all && !Path::new(&dir.path).is_dir() {
            continue;
        }
        if let Some(ex) = exclude {
            if dir.path == ex || dir.path.starts_with(&(ex.to_string() + "/")) {
                continue;
            }
        }
        if let Some(bd) = base_dir {
            if !dir.path.starts_with(bd) {
                continue;
            }
        }

        if !matches_keywords(&dir.path, keywords) {
            continue;
        }

        let score = dir.query_score(now);
        matches.push((dir, score));
    }

    matches.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(Ordering::Equal));
    matches.reverse();

    matches
}
EOF"}

