        ("powershell", "none", true) => include_str!("templates/powershell_none_nocmd.txt"),

        ("tcsh", "pwd", false) => include_str!("templates/tcsh_pwd_cmd.txt"),
        ("tcsh", "pwd", true) => include_str!("templates/tcsh_pwd_nocmd.txt"),
        ("tcsh", "prompt", false) => include_str!("templates/tcsh_prompt_cmd.txt"),
