        ("tcsh", "none", true) => include_str!("templates/tcsh_none_nocmd.txt"),

        ("xonsh", "pwd", false) => include_str!("templates/xonsh_pwd_cmd.txt"),
        ("xonsh", "pwd", true) => include_str!("templates/xonsh_pwd_nocmd.txt"),
        ("xonsh", "prompt", false) => include_str!("templates/xonsh_prompt_cmd.txt"),
        ("xonsh", "prompt", true) => include_str!("templates/xonsh_prompt_nocmd.txt"),
        ("xonsh", "none", false) => include_str!("templates/xonsh_none_cmd.txt"),
        ("xonsh", "none", true) => include_str!("templates/xonsh_none_nocmd.txt"),

        ("zsh", "pwd", false) => include_str!("templates/zsh_pwd_cmd.txt"),
        ("zsh", "pwd", true) => include_str!("templates/zsh_pwd_nocmd.txt"),
        ("zsh", "prompt", false) => include_str!("templates/zsh_prompt_cmd.txt"),
        ("zsh", "prompt", true) => include_str!("templates/zsh_prompt_nocmd.txt"),
        ("zsh", "none", false) => include_str!("templates/zsh_none_cmd.txt"),
        ("zsh", "none", true) => include_str!("templates/zsh_none_nocmd.txt"),

        _ => unreachable!(),
    };

    if no_cmd || cmd == "z" {
        return template.to_string();
    }

    match shell {
        "bash" => {
            let res = template.replace("\\builtin unalias z &>/dev/null", &format!("\\builtin unalias {} &>/dev/null", cmd));
            let res = res.replace("function z() {", &format!("function {}() {{", cmd));
            let res = res.replace("\\builtin unalias zi &>/dev/null", &format!("\\builtin unalias {}i &>/dev/null", cmd));
            let res = res.replace("function zi() {", &format!("function {}i() {{", cmd));
            let res = res.replace("READLINE_LINE=\"z ${__zoxide_result@Q}\"", &format!("READLINE_LINE=\"{} ${{__zoxide_result@Q}}\"", cmd));
            let res = res.replace("\\builtin complete -F __zoxide_z_complete -o filenames -- z", &format!("\\builtin complete -F __zoxide_z_complete -o filenames -- {}", cmd));
            let res = res.replace("\\builtin complete -r zi &>/dev/null", &format!("\\builtin complete -r {}i &>/dev/null", cmd));
            res
        }
        "elvish" => {
            let res = template.replace("edit:add-var z~", &format!("edit:add-var {}~", cmd));
            let res = res.replace("edit:add-var zi~", &format!("edit:add-var {}i~", cmd));
            let res = res.replace("set edit:completion:arg-completer[z]", &format!("set edit:completion:arg-completer[{}]", cmd));
            res
        }
        "fish" => {
            let res = template.replace("abbr --erase z &>/dev/null", &format!("abbr --erase {} &>/dev/null", cmd));
            let res = res.replace("complete --erase --command z", &format!("complete --erase --command {}", cmd));
            let res = res.replace("alias z=__zoxide_z", &format!("alias {}=__zoxide_z", cmd));
            let res = res.replace("abbr --erase zi &>/dev/null", &format!("abbr --erase {}i &>/dev/null", cmd));
            let res = res.replace("complete --erase --command zi", &format!("complete --erase --command {}i", cmd));
            let res = res.replace("alias zi=__zoxide_zi", &format!("alias {}i=__zoxide_zi", cmd));
            let res = res.replace("complete --command z --no-files", &format!("complete --command {} --no-files", cmd));
            let res = res.replace("complete --command z --arguments", &format!("complete --command {} --arguments", cmd));
            let res = res.replace("complete --command zi --no-files", &format!("complete --command {}i --no-files", cmd));
            let res = res.replace("complete --command zi --arguments", &format!("complete --command {}i --arguments", cmd));
            res
        }
        "nushell" => {
            let res = template.replace("alias z = __zoxide_z", &format!("alias {} = __zoxide_z", cmd));
            let res = res.replace("alias zi = __zoxide_zi", &format!("alias {}i = __zoxide_zi", cmd));
            res
        }
        "posix" => {
            let res = template.replace("\\command unalias z >/dev/null 2>&1 || \\true", &format!("\\command unalias {} >/dev/null 2>&1 || \\true", cmd));
            let res = res.replace("z() {", &format!("{}() {{", cmd));
            let res = res.replace("\\command unalias zi >/dev/null 2>&1 || \\true", &format!("\\command unalias {}i >/dev/null 2>&1 || \\true", cmd));
            let res = res.replace("zi() {", &format!("{}i() {{", cmd));
            res
        }
        "powershell" => {
            let res = template.replace("Set-Alias -Name z -Value", &format!("Set-Alias -Name {} -Value", cmd));
            let res = res.replace("Set-Alias -Name zi -Value", &format!("Set-Alias -Name {}i -Value", cmd));
            res
        }
        "tcsh" => {
            let res = template.replace("alias z __zoxide_z", &format!("alias {} __zoxide_z", cmd));
            let res = res.replace("alias zi __zoxide_zi", &format!("alias {}i __zoxide_zi", cmd));
            res
        }
        "xonsh" => {
            let res = template.replace("builtins.aliases[\"z\"]", &format!("builtins.aliases[\"{}\"]", cmd));
            let res = res.replace("builtins.aliases[\"zi\"]", &format!("builtins.aliases[\"{}i\"]", cmd));
            res
        }
        "zsh" => {
            let res = template.replace("function z() {", &format!("function {}() {{", cmd));
            let res = res.replace("function zi() {", &format!("function {}i() {{", cmd));
            let res = res.replace("BUFFER=\"z ${(q-)__zoxide_result}\"", &format!("BUFFER=\"{} ${(q-)__zoxide_result}\"", cmd));
            let res = res.replace("functions[compdef]\" -ne 0 ]] && \\compdef __zoxide_z_complete z", &format!("functions[compdef]\" -ne 0 ]] && \\compdef __zoxide_z_complete {}", cmd));
            res
        }
        _ => template.to_string(),
    }
}
EOF"}

