{"command":"cat << 'EOF' > src/import.rs
use crate::db::{Database, Dir};
use std::cmp::max;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

pub fn import(from: &str, file_path: &Path, merge: bool, db_path: &Path) -> anyhow::Result<()> {
    let mut db = if merge {
        Database::read(db_path).unwrap_or(Database { dirs: Vec::new() })
    } else {
        Database { dirs: Vec::new() }
    };

    let file = File::open(file_path)?;
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let (path_str, score, now) = match from {
            "z" => {
                let parts: Vec<&str> = trimmed.split('|').collect();
                if parts.len() < 3 {
                    continue;
                }
                let path = parts[0].to_string();
                let score: f64 = parts[1].parse().unwrap_or(1.0);
                let now: u64 = parts[2].parse().unwrap_or(0);
                (path, score, now)
            }
            "autojump" => {
                let parts: Vec<&str> = trimmed.split('\t').collect();
                if parts.len() < 2 {
                    continue;
                }
                let aj_score: f64 = parts[0].parse().unwrap_or(1.0);
                let path = parts[1].to_string();
                let score = 1.0 / (1.0 + (-aj_score).exp());
                (path, score, 0u64)
            }
            _ => anyhow::bail!("unknown import source"),
        };

        if let Some(existing) = db.dirs.iter_mut().find(|d| d.path == path_str) {
            existing.rank += score;
            existing.last_accessed = max(existing.last_accessed, now);
        } else {
            db.dirs.push(Dir {
                path: path_str,
                rank: score,
                last_accessed: now,
            });
        }
    }

    db.save(db_path)?;
    Ok(())
}
EOF

cat << 'EOF' > src/edit.rs
use crate::db::Database;
use std::env;
use std::io::Write;
use std::path::Path;
use std::process::Command;

pub fn handle_edit_cmd(subcmd: Option<&str>, args: &[String], db_path: &Path) -> anyhow::Result<()> {
    match subcmd {
        Some("reload") => {
            let db = Database::read(db_path)?;
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();
            let mut stdout = std::io::stdout();
            for dir in &db.dirs {
                let score = dir.query_score(now).min(9999.0);
                write!(stdout, "{:>6.1}\t{}\0", score, dir.path)?;
            }
            Ok(())
        }
        Some("delete") => {
            if let Some(target) = args.first() {
                let mut db = Database::read(db_path)?;
                db.dirs.retain(|d| d.path != *target);
                db.save(db_path)?;
            }
            Ok(())
        }
        Some("increment") => {
            if let Some(target) = args.first() {
                let mut db = Database::read(db_path)?;
                if let Some(dir) = db.dirs.iter_mut().find(|d| d.path == *target) {
                    dir.rank += 1.0;
                }
                db.save(db_path)?;
            }
            Ok(())
        }
        Some("decrement") => {
            if let Some(target) = args.first() {
                let mut db = Database::read(db_path)?;
                if let Some(dir) = db.dirs.iter_mut().find(|d| d.path == *target) {
                    dir.rank = (dir.rank - 1.0).max(0.0);
                }
                db.save(db_path)?;
            }
            Ok(())
        }
        None => {
            let exe = env::current_exe()?;
            let exe_str = exe.to_string_lossy();
            let reload_cmd = format!("{} edit reload", exe_str);
            let delete_cmd = format!("{} edit delete {{2..}}", exe_str);
            let inc_cmd = format!("{} edit increment {{2..}}", exe_str);
            let dec_cmd = format!("{} edit decrement {{2..}}", exe_str);

            let bind_str = format!(
                "btab:up,ctrl-r:reload({}),ctrl-d:reload({}),ctrl-w:reload({}),ctrl-s:reload({}),ctrl-z:ignore,double-click:ignore,enter:abort,start:reload({}),tab:down",
                reload_cmd, delete_cmd, inc_cmd, dec_cmd, reload_cmd
            );

            let mut fzf_cmd = Command::new("fzf");
            fzf_cmd
                .arg("--delimiter=\t")
                .arg("--nth=2")
                .arg("--read0")
                .arg("--exact")
                .arg("--no-sort")
                .arg(format!("--bind={}", bind_str))
                .arg("--cycle")
                .arg("--keep-right")
                .arg("--border=sharp")
                .arg("--border-label=  zoxide-edit  ")
                .arg("--header=ctrl-r:reload\tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH")
                .arg("--info=inline")
                .arg("--layout=reverse")
                .arg("--padding=1,0,0,0")
                .arg("--color=label:bold")
                .arg("--tabstop=1");

            if let Ok(opts) = env::var("_ZO_FZF_OPTS") {
                if !opts.is_empty() {
                    for opt in opts.split_whitespace() {
                        fzf_cmd.arg(opt);
                    }
                }
            }

            let status = fzf_cmd.status().map_err(|_| {
                anyhow::anyhow!("zoxide: could not find fzf, is it installed?")
            })?;

            if !status.success() {
                // Exit status check if needed
            }

            Ok(())
        }
        _ => Ok(()),
    }
}
EOF"}

