use std::path::Path;
use std::process::Command;

pub fn handle_edit_cmd(subcmd: Option<&str>, args: &[String], db_path: &Path) -> anyhow::Result<()> {
    match subcmd {
        Some("reload") => {
            let db = Database::read(db_path)?;
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();
