use clap::{Arg, ArgAction, Command};
use std::env;
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Command as ProcessCommand, Stdio};
use std::time::SystemTime;

mod db;
mod edit;
mod import;
mod init;
mod query;

use db::*;
use query::*;

const AFTER_HELP: &str = "\
Environment variables:
  _ZO_DATA_DIR          Path for zoxide data files
  _ZO_ECHO              Print the matched directory before navigating to it when set to 1
  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded
  _ZO_FZF_OPTS          Custom flags to pass to fzf
  _ZO_MAXAGE            Maximum total age after which entries start getting deleted
  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths";

fn build_cli() -> Command {
    Command::new("zoxide")
        .version("0.9.9")
        .author("Ajeet D'Souza <98ajeet@gmail.com>\nhttps://github.com/ajeetdsouza/zoxide")
        .about("A smarter cd command for your terminal")
        .after_help(AFTER_HELP)
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            Command::new("add")
                .bin_name("zoxide-add")
                .about("Add a new directory or increment its rank")
                .after_help(AFTER_HELP)
                .arg(
                    Arg::new("paths")
                        .value_name("PATHS")
                        .required(true)
                        .action(ArgAction::Append),
                )
                .arg(
                    Arg::new("score")
                        .short('s')
                        .long("score")
                        .value_name("SCORE")
                        .help("The rank to increment the entry if it exists or initialize it with if it doesn't")
                        .value_parser(clap::value_parser!(f64)),
                ),
        )
        .subcommand(
            Command::new("edit")
                .bin_name("zoxide-edit")
                .about("Edit the database")
                .after_help(AFTER_HELP)
                .arg(
                    Arg::new("subcmd")
                        .hide(true)
                        .index(1)
                        .required(false),
                )
                .arg(
                    Arg::new("args")
                        .hide(true)
                        .index(2)
                        .action(ArgAction::Append)
                        .required(false),
                ),
        )
        .subcommand(
            Command::new("import")
                .bin_name("zoxide-import")
                .about("Import entries from another application")
                .after_help(AFTER_HELP)
                .arg(
                    Arg::new("from")
                        .long("from")
                        .value_name("FROM")
                        .required(true)
                        .help("Application to import from")
                        .value_parser(["autojump", "z"]),
                )
                .arg(
                    Arg::new("merge")
                        .long("merge")
                        .action(ArgAction::SetTrue)
                        .help("Merge into existing database"),
                )
                .arg(
                    Arg::new("path")
                        .value_name("PATH")
                        .required(true),
                ),
        )
        .subcommand(
            Command::new("init")
                .bin_name("zoxide-init")
                .about("Generate shell configuration")
                .after_help(AFTER_HELP)
                .arg(
                    Arg::new("shell")
                        .value_name("SHELL")
                        .required(true)
                        .value_parser(["bash", "elvish", "fish", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"]),
                )
                .arg(
                    Arg::new("no-cmd")
                        .long("no-cmd")
                        .action(ArgAction::SetTrue)
                        .help("Prevents zoxide from defining the `z` and `zi` commands"),
                )
                .arg(
                    Arg::new("cmd")
                        .long("cmd")
                        .value_name("CMD")
                        .default_value("z")
                        .help("Changes the prefix of the `z` and `zi` commands"),
                )
                .arg(
                    Arg::new("hook")
                        .long("hook")
                        .value_name("HOOK")
                        .default_value("pwd")
                        .value_parser(["none", "prompt", "pwd"])
                        .help("Changes how often zoxide increments a directory's score"),
                ),
        )
        .subcommand(
            Command::new("query")
                .bin_name("zoxide-query")
                .about("Search for a directory in the database")
                .after_help(AFTER_HELP)
                .arg(
                    Arg::new("keywords")
                        .value_name("KEYWORDS")
                        .action(ArgAction::Append),
                )
                .arg(
                    Arg::new("all")
                        .short('a')
                        .long("all")
                        .action(ArgAction::SetTrue)
                        .help("Show unavailable directories"),
                )
                .arg(
                    Arg::new("interactive")
                        .short('i')
                        .long("interactive")
                        .action(ArgAction::SetTrue)
                        .conflicts_with("list")
                        .help("Use interactive selection"),
                )
                .arg(
                    Arg::new("list")
                        .short('l')
                        .long("list")
                        .action(ArgAction::SetTrue)
                        .conflicts_with("interactive")
                        .help("List all matching directories"),
                )
                .arg(
                    Arg::new("score")
                        .short('s')
                        .long("score")
                        .action(ArgAction::SetTrue)
                        .help("Print score with results"),
                )
                .arg(
                    Arg::new("exclude")
                        .long("exclude")
                        .value_name("path")
                        .help("Exclude the current directory"),
                )
                .arg(
                    Arg::new("base-dir")
                        .long("base-dir")
                        .value_name("path")
                        .help("Only search within this directory"),
                ),
        )
        .subcommand(
            Command::new("remove")
                .bin_name("zoxide-remove")
                .about("Remove a directory from the database")
                .after_help(AFTER_HELP)
                .arg(
                    Arg::new("paths")
                        .value_name("PATHS")
                        .action(ArgAction::Append),
                ),
        )
}

fn main() -> anyhow::Result<()> {
    let matches = build_cli().get_matches();

    let db_path = match get_db_path() {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let max_age = match get_max_age() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let resolve_symlinks = env::var("_ZO_RESOLVE_SYMLINKS").unwrap_or_default() == "1";

    match matches.subcommand() {
        Some(("add", sub_m)) => {
            let paths: Vec<&String> = sub_m.get_many::<String>("paths").unwrap().collect();
            let score_delta = sub_m.get_one::<f64>("score").copied().unwrap_or(1.0);

            let mut db = Database::read(&db_path)?;
            let mut has_error = false;

            for p in paths {
                let resolved = match resolve_path(p, resolve_symlinks) {
                    Ok(r) => r,
                    Err(_) => {
                        eprintln!("zoxide: not a directory: {}", p);
                        has_error = true;
                        continue;
                    }
                };

                if !Path::new(&resolved).is_dir() {
                    eprintln!("zoxide: not a directory: {}", p);
                    has_error = true;
                    continue;
                }

                match is_excluded(&resolved) {
                    Ok(true) => continue,
                    Ok(false) => {}
                    Err(e) => {
                        eprintln!("{}", e);
                        std::process::exit(1);
                    }
                }

                if let Some(existing) = db.dirs.iter_mut().find(|d| d.path == resolved) {
                    existing.rank += score_delta;
                    existing.last_accessed = now;
                } else {
                    db.dirs.push(Dir {
                        path: resolved,
                        rank: score_delta,
                        last_accessed: now,
                    });
                }
            }

            age_database(&mut db, max_age);
            db.save(&db_path)?;

            if has_error {
                std::process::exit(1);
            }
        }
        Some(("edit", sub_m)) => {
            let subcmd = sub_m.get_one::<String>("subcmd").map(|s| s.as_str());
            let args: Vec<String> = sub_m
                .get_many::<String>("args")
                .map(|v| v.cloned().collect())
                .unwrap_or_default();

            if let Err(e) = edit::handle_edit_cmd(subcmd, &args, &db_path) {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
        Some(("import", sub_m)) => {
            let from = sub_m.get_one::<String>("from").unwrap();
            let merge = sub_m.get_flag("merge");
            let file_path_str = sub_m.get_one::<String>("path").unwrap();
            let file_path = Path::new(file_path_str);

            if let Err(e) = import::import(from, file_path, merge, &db_path) {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
        Some(("init", sub_m)) => {
            let shell = sub_m.get_one::<String>("shell").unwrap();
            let no_cmd = sub_m.get_flag("no-cmd");
            let cmd = sub_m.get_one::<String>("cmd").unwrap();
            let hook = sub_m.get_one::<String>("hook").unwrap();

            let result = init::init(shell, hook, cmd, no_cmd);
            print!("{}", result);
        }
        Some(("query", sub_m)) => {
            let keywords: Vec<String> = sub_m
                .get_many::<String>("keywords")
                .map(|v| v.cloned().collect())
                .unwrap_or_default();
            let all = sub_m.get_flag("all");
            let interactive = sub_m.get_flag("interactive");
            let list = sub_m.get_flag("list");
            let score_flag = sub_m.get_flag("score");
            let exclude = sub_m.get_one::<String>("exclude").map(|s| s.as_str());
            let base_dir = sub_m.get_one::<String>("base-dir").map(|s| s.as_str());

            let db = Database::read(&db_path)?;
            let matches = query_matches(&db.dirs, &keywords, now, all, exclude, base_dir);

            if matches.is_empty() {
                eprintln!("zoxide: no match found");
                std::process::exit(1);
            }

            if interactive {
                let mut input_buf = Vec::new();
                for (dir, score) in &matches {
                    let sc = score.min(9999.0);
                    let line = format!("{:>6.1}\t{}\0", sc, dir.path);
                    input_buf.extend_from_slice(line.as_bytes());
                }

                let exe = env::current_exe()?;
                let exe_str = exe.to_string_lossy();

                let bind_str = "ctrl-z:ignore,btab:up,tab:down";

                let mut fzf_cmd = ProcessCommand::new("fzf");
                fzf_cmd
                    .arg("--delimiter=\t")
                    .arg("--nth=2")
                    .arg("--read0")
                    .arg("--exact")
                    .arg("--no-sort")
                    .arg(format!("--bind={}", bind_str))
                    .arg("--cycle")
                    .arg("--keep-right")
                    .arg("--border=sharp")
                    .arg("--height=45%")
                    .arg("--info=inline")
                    .arg("--layout=reverse")
                    .arg("--tabstop=1")
                    .arg("--exit-0")
                    .stdin(Stdio::piped())
                    .stdout(Stdio::piped());

                if let Ok(opts) = env::var("_ZO_FZF_OPTS") {
                    if !opts.is_empty() {
                        for opt in opts.split_whitespace() {
                            fzf_cmd.arg(opt);
                        }
                    }
                }

                let mut child = match fzf_cmd.spawn() {
                    Ok(c) => c,
                    Err(_) => {
                        eprintln!("zoxide: could not find fzf, is it installed?");
                        std::process::exit(1);
                    }
                };

                if let Some(mut stdin) = child.stdin.take() {
                    let _ = stdin.write_all(&input_buf);
                }

                let output = child.wait_with_output()?;
                if output.status.success() {
                    let out_str = String::from_utf8_lossy(&output.stdout);
                    let line = out_str.trim();
                    if let Some(tab_idx) = line.find('\t') {
                        let path = &line[tab_idx + 1..];
                        println!("{}", path);
                    } else if !line.is_empty() {
                        println!("{}", line);
                    }
                } else {
                    eprintln!("zoxide: could not read selection from fzf");
                    std::process::exit(1);
                }
            } else if list {
                for (dir, score) in matches {
                    if score_flag {
                        let sc = score.min(9999.0);
                        println!("{:>6.1} {}", sc, dir.path);
                    } else {
                        println!("{}", dir.path);
                    }
                }
            } else {
                if let Some((top_dir, score)) = matches.first() {
                    if score_flag {
                        let sc = score.min(9999.0);
                        println!("{:>6.1} {}", sc, top_dir.path);
                    } else {
                        println!("{}", top_dir.path);
                    }
                }
            }
        }
        Some(("remove", sub_m)) => {
            let paths: Vec<&String> = sub_m
                .get_many::<String>("paths")
                .map(|v| v.collect())
                .unwrap_or_default();

            let mut db = Database::read(&db_path)?;
            let mut has_error = false;

            for p in paths {
                let resolved = match resolve_path(p, resolve_symlinks) {
                    Ok(r) => r,
                    Err(_) => p.to_string(),
                };

                let pos = db.dirs.iter().position(|d| d.path == resolved || d.path == *p);
                if let Some(idx) = pos {
                    db.dirs.remove(idx);
                } else {
                    eprintln!("zoxide: path not found in database: {}", p);
                    has_error = true;
                }
            }

            db.save(&db_path)?;

            if has_error {
                std::process::exit(1);
            }
        }
        _ => {}
    }

    Ok(())
}
EOF"}

